*{box-sizing:border-box}body{margin:0;background:#f1f5fa;color:#173d5b;font-family:Cairo,Tahoma,sans-serif;line-height:1.8}a{color:#13538a;text-decoration:none}a:hover{text-decoration:underline}button,input,select{font:inherit}.container{max-width:1220px;margin:auto;padding:0 22px}.top{background:#fff;border-bottom:1px solid #dce5ef;box-shadow:0 2px 16px #0d36500a}.top-inner{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:16px;padding-bottom:16px}.brand{display:flex;align-items:center;gap:12px;font-size:19px;font-weight:800;color:#143e60}.brand-mark{display:grid;place-items:center;width:48px;height:48px;border-radius:13px;background:#15558b;color:white;font-size:25px;box-shadow:0 6px 14px #104a7b2b}.brand small{display:block;color:#688096;font-size:11px;font-weight:600;line-height:1.5}.nav a{font-weight:700;padding:9px 13px;border-radius:9px}.nav a[aria-current="page"]{background:#e9f3fb;color:#104b7c}.nav{display:flex;gap:16px;flex-wrap:wrap}.hero{position:relative;overflow:hidden;background:linear-gradient(115deg,#103a5c,#18598d);color:white;padding:48px 0 55px}.hero:before{content:"";position:absolute;inset:auto auto -130px -90px;width:360px;height:360px;border:1px solid #ffffff17;border-radius:50%;box-shadow:0 0 0 50px #ffffff08,0 0 0 105px #ffffff05;pointer-events:none}.hero-inner{position:relative;display:flex;align-items:center;justify-content:space-between;gap:24px}.hero-kicker{display:inline-block;color:#c9e4f5;font-weight:700;font-size:13px;margin-bottom:8px}.hero-shortcut{display:inline-flex;align-items:center;gap:8px;border:1px solid #ffffff65;border-radius:11px;padding:11px 18px;color:#fff;font-weight:700;white-space:nowrap}.hero-shortcut:hover{background:#ffffff16;color:#fff;text-decoration:none}.hero h1{font-size:clamp(26px,4vw,36px);margin:0 0 8px}.hero p{margin:0;color:#e3edf7}.main{padding-top:28px;padding-bottom:50px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:25px}.stat,.panel{background:white;border:1px solid #dae5ee;border-radius:17px;box-shadow:0 8px 25px #173d5b0a}.stat{padding:21px}.stat .name{color:#60788c;font-size:13px}.stat strong{display:block;margin-top:10px;font-size:24px;font-weight:800;color:#12558c}.stat .note{font-size:12px;color:#708296}.money{display:inline-flex;direction:ltr;unicode-bidi:isolate;align-items:baseline;gap:5px;white-space:nowrap;font-family:Arial,sans-serif;font-variant-numeric:tabular-nums}.money .currency{font-family:Cairo,sans-serif;font-size:.65em}.panel{padding:22px;margin-bottom:20px}.panel-title{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:18px}.panel-title h2{margin:0;font-size:21px}.filters{display:grid;grid-template-columns:minmax(190px,1.6fr) minmax(135px,1fr) minmax(145px,1fr) repeat(2,minmax(170px,1fr)) auto auto;gap:12px;align-items:end}.date-selects{display:grid;grid-template-columns:1fr 1.3fr 1.5fr;gap:5px;direction:rtl}.date-selects select{min-width:0;padding:9px 4px;text-align:center;font-size:12px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:6px}.field input,.field select{width:100%;min-height:45px;padding:9px 12px;border:1px solid #ccd9e5;border-radius:10px;background:#fff;color:#183b5b}.btn{display:inline-flex;justify-content:center;align-items:center;min-height:45px;padding:9px 17px;border-radius:10px;border:1px solid #cbd8e4;font-weight:700;cursor:pointer;white-space:nowrap}.btn-primary{background:#15578f;color:#fff;border-color:#15578f}.btn-primary:hover{background:#103e6a;color:white;text-decoration:none}.btn-outline{background:#fff;color:#16476d}.btn-outline:hover{text-decoration:none;background:#f0f6fa}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:1040px}th,td{padding:13px 12px;text-align:right;border-bottom:1px solid #e4ebf1;font-size:13px;vertical-align:middle}th{background:#edf4f9;color:#37576d;font-weight:800}tbody tr:hover{background:#f8fbfe}.badge{display:inline-flex;border-radius:25px;padding:3px 12px;font-size:12px;font-weight:800;white-space:nowrap}.PENDING{background:#fff1d4;color:#8b5b00}.APPROVED{background:#ddf5e7;color:#166b3c}.REJECTED,.CANCELLED{background:#fee4e4;color:#a02c2c}.note-cell{max-width:220px;overflow-wrap:anywhere}.empty{text-align:center;padding:45px 18px;color:#5e7181}.empty h3{color:#143e5e}.pagination{margin-top:20px}.footnote{color:#667c8e;font-size:13px}.reference{direction:ltr;unicode-bidi:isolate;display:inline-block;font-family:Arial,sans-serif;font-weight:700}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}:focus-visible{outline:3px solid #e8aa33;outline-offset:3px}@media(max-width:1100px){.filters{grid-template-columns:repeat(3,minmax(0,1fr))}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.hero-inner{align-items:flex-start;flex-direction:column}.hero{padding:35px 0 40px}.nav{gap:3px}.nav a{padding:7px 9px;font-size:13px}.container{padding-left:14px;padding-right:14px}.top-inner{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:1fr 1fr;gap:9px}.stat{padding:14px}.stat strong{font-size:18px}.filters{grid-template-columns:1fr}.panel{padding:15px}.panel-title{align-items:flex-start;flex-direction:column}}
.date-field .date-input-wrap{position:relative}.date-field input[type="date"]{font-family:Cairo,Arial,sans-serif;font-size:14px;direction:ltr;text-align:center;color:#173d5b;padding-inline:12px;min-width:0;cursor:pointer}.date-field input[type="date"]::-webkit-calendar-picker-indicator{cursor:pointer;opacity:.8}.date-hint{display:block;font-size:11px;color:#6b8296;margin-top:4px}.date-field input:focus-visible{outline:2px solid #15578f;outline-offset:2px}@media(max-width:1250px){.filters{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:650px){.filters{grid-template-columns:1fr}}

