<script>
(()=>{
'use strict';
const months=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const week=['ح','ن','ث','ر','خ','ج','س'];
const two=n=>String(n).padStart(2,'0');
const parse=v=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(v||''))return null;const [y,m,d]=v.split('-').map(Number);const x=new Date(y,m-1,d);return x.getFullYear()===y&&x.getMonth()===m-1&&x.getDate()===d?x:null};
const iso=d=>`${d.getFullYear()}-${two(d.getMonth()+1)}-${two(d.getDate())}`;
const display=d=>d?`${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`:'يوم / شهر / سنة';
const dialog=document.createElement('div');dialog.className='date-dialog';dialog.hidden=true;dialog.setAttribute('role','dialog');dialog.setAttribute('aria-label','اختيار التاريخ');document.body.appendChild(dialog);
let active=null,viewYear=0,viewMonth=0;
function close(){dialog.hidden=true;if(active){active.setAttribute('aria-expanded','false');active.focus({preventScroll:true})}active=null}
function render(){
 const head=document.createElement('div');head.className='calendar-heading';
 const prev=document.createElement('button');prev.type='button';prev.className='calendar-arrow';prev.textContent='›';prev.setAttribute('aria-label','الشهر السابق');prev.onclick=()=>move(-1);
 const next=document.createElement('button');next.type='button';next.className='calendar-arrow';next.textContent='‹';next.setAttribute('aria-label','الشهر التالي');next.onclick=()=>move(1);
 const title=document.createElement('strong');title.textContent=`${months[viewMonth]} ${viewYear}`;
 head.append(prev,title,next);
 const weekdays=document.createElement('div');weekdays.className='calendar-week';week.forEach(w=>{const s=document.createElement('span');s.textContent=w;weekdays.appendChild(s)});
 const grid=document.createElement('div');grid.className='calendar-days';const offset=new Date(viewYear,viewMonth,1).getDay();const count=new Date(viewYear,viewMonth+1,0).getDate();
 for(let i=0;i<offset;i++){const e=document.createElement('span');e.className='calendar-empty';grid.appendChild(e)}
 const current=parse(document.getElementById(active.dataset.dateTarget).value);
 for(let day=1;day<=count;day++){const b=document.createElement('button');b.type='button';b.textContent=String(day);const selected=!!current&&current.getFullYear()===viewYear&&current.getMonth()===viewMonth&&current.getDate()===day;b.setAttribute('aria-pressed',String(selected));b.setAttribute('aria-label',`${day} ${months[viewMonth]} ${viewYear}`);b.onclick=()=>{const input=document.getElementById(active.dataset.dateTarget);input.value=iso(new Date(viewYear,viewMonth,day));document.getElementById(input.id+'-display').textContent=display(parse(input.value));close()};grid.appendChild(b)}
 const actions=document.createElement('div');actions.className='calendar-actions';const today=document.createElement('button');today.type='button';today.className='calendar-today';today.textContent='اليوم';today.onclick=()=>{const d=new Date();viewYear=d.getFullYear();viewMonth=d.getMonth();render()};const clear=document.createElement('button');clear.type='button';clear.className='calendar-clear';clear.textContent='مسح التاريخ';clear.onclick=()=>{const input=document.getElementById(active.dataset.dateTarget);input.value='';document.getElementById(input.id+'-display').textContent=display(null);close()};actions.append(today,clear);
 dialog.replaceChildren(head,weekdays,grid,actions);
}
function move(amount){const d=new Date(viewYear,viewMonth+amount,1);viewYear=d.getFullYear();viewMonth=d.getMonth();render()}
function place(){if(!active)return;const r=active.getBoundingClientRect();const width=Math.min(330,innerWidth-24);const left=Math.max(12,Math.min(innerWidth-width-12,r.right-width));const top=r.bottom+8+315>innerHeight&&r.top>330?r.top-330:r.bottom+8;dialog.style.left=left+'px';dialog.style.top=Math.max(8,top)+'px'}
document.querySelectorAll('[data-date-target]').forEach(btn=>{const input=document.getElementById(btn.dataset.dateTarget);document.getElementById(input.id+'-display').textContent=display(parse(input.value));btn.addEventListener('click',()=>{if(active===btn&&!dialog.hidden){close();return}if(active)active.setAttribute('aria-expanded','false');active=btn;btn.setAttribute('aria-expanded','true');const date=parse(input.value)||new Date();viewYear=date.getFullYear();viewMonth=date.getMonth();render();dialog.hidden=false;place()})});
document.addEventListener('pointerdown',e=>{if(!dialog.hidden&&!dialog.contains(e.target)&&!e.target.closest('[data-date-target]'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.hidden){e.preventDefault();close()}});window.addEventListener('resize',()=>{if(!dialog.hidden)place()});window.addEventListener('scroll',()=>{if(!dialog.hidden)place()},true);
})();
</script>
</body></html>